func (this *Bitbank) fetchTickerBody(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": market["id"],
	}

	r1 := <-this.PublicGetPairTicker(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var data map[string]any = this.SafeDictMap(response, "data", map[string]any{})

	ch <- AsyncResult[Ticker]{Value: this.ParseTicker(data, market)}
	return nil
}

