func (this *Bitbank) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades
	//
	//    {
	//        "transaction_id": "1143247037",
	//        "side": "buy",
	//        "price": "3836025",
	//        "amount": "0.0005",
	//        "executed_at": "1694249441593"
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(trade, "executed_at")
	var marketResolved map[string]any = this.SafeMarket(nil, market)
	var priceString *string = this.SafeString(trade, "price")
	var amountString *string = this.SafeString(trade, "amount")
	var id *string = this.SafeString2(trade, "transaction_id", "trade_id")
	var takerOrMaker *string = this.SafeString(trade, "maker_taker")
	var fee map[string]any = nil
	var feeCostString *string = this.SafeString(trade, "fee_amount_quote")
	if feeCostString != nil {
		fee = map[string]any{
			"currency": marketResolved["quote"],
			"cost":     feeCostString,
		}
	}
	var orderId *string = this.SafeString(trade, "order_id")
	var typeVar *string = this.SafeString(trade, "type")
	var side *string = this.SafeString(trade, "side")
	return this.SafeTrade(map[string]any{
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       marketResolved["symbol"],
		"id":           id,
		"order":        orderId,
		"type":         typeVar,
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"fee":          fee,
		"info":         trade,
	}, marketResolved)
}

