/**
 * @method
 * @name bitbank#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/public-api.md#candlestick
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Bitbank) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitbank) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// it doesn't have any defaults, might return 200, might 2000 (i.e. https://public.bitbank.cc/btc_jpy/candlestick/4hour/2020)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var windowLimit any = func() any {
		if limit == nil {
			return 1000
		}
		return limit
	}()
	var limitResolved any = func() any {
		if since == nil {
			return windowLimit
		}
		return limit
	}()
	var duration int64 = this.ParseTimeframe(timeframe)
	var windowMs int64 = (duration * 1000) * 1000
	if limit != nil {
		windowMs = (duration * 1000) * *limit
	}
	var sinceResolved any = func() any {
		if since == nil {
			return (this.Milliseconds() - windowMs)
		}
		return since
	}()
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair":       market["id"],
		"candletype": this.SafeString(this.Timeframes, timeframe, timeframe),
		"yyyymmdd":   this.Yyyymmdd(sinceResolved, ""),
	}

	r1 := <-this.PublicGetPairCandlestickCandletypeYyyymmdd(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "success":1,
	//         "data":{
	//             "candlestick":[
	//                 {
	//                     "type":"5min",
	//                     "ohlcv":[
	//                         ["0.02501786","0.02501786","0.02501786","0.02501786","0.0000",1591488000000],
	//                         ["0.02501747","0.02501953","0.02501747","0.02501953","0.3017",1591488300000],
	//                         ["0.02501762","0.02501762","0.02500392","0.02500392","0.1500",1591488600000],
	//                     ]
	//                 }
	//             ],
	//             "timestamp":1591508668190
	//         }
	//     }
	//
	var data map[string]any = SafeMapTyped(response, "data")
	var candlestick []any = SafeListTyped(data, "candlestick")
	var first map[string]any = SafeMapTyped(candlestick, 0)
	var ohlcv []any = SafeListTypedDefault(first, "ohlcv", []any{})

	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(ohlcv, market, timeframe, sinceResolved, limitResolved))}
	return nil
}
func (this *Bitbank) ParseBalance(response any) map[string]any {
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": nil,
		"datetime":  nil,
	}
	var data map[string]any = SafeMapTyped(response, "data")
	var assets []any = SafeListTyped(data, "assets")
	for i := 0; i < len(assets); i++ {
		var balance map[string]any = SafeMapTyped(assets, i)
		var currencyId *string = this.SafeString(balance, "asset")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(balance, "free_amount")
		account["used"] = this.SafeString(balance, "locked_amount")
		account["total"] = this.SafeString(balance, "onhand_amount")
		if code != nil {
			result[*code] = account
		}
	}
	return this.SafeBalance(result).(map[string]any)
}

