func (this *Bitbank) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"UNFILLED":                  "open",
		"PARTIALLY_FILLED":          "open",
		"FULLY_FILLED":              "closed",
		"CANCELED_UNFILLED":         "canceled",
		"CANCELED_PARTIALLY_FILLED": "canceled",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitbank) ParseOrder(order any, optionalArgs ...any) Order {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "order_id")
	var marketId *string = this.SafeString(order, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(order, "ordered_at")
	var price *string = this.SafeString(order, "price")
	var amount *string = this.SafeString(order, "start_amount")
	var filled *string = this.SafeString(order, "executed_amount")
	var remaining *string = this.SafeString(order, "remaining_amount")
	var average *string = this.SafeString(order, "average_price")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var typeVar *string = this.SafeStringLower(order, "type")
	var side *string = this.SafeStringLower(order, "side")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"datetime":           this.Iso8601(timestamp),
		"timestamp":          timestamp,
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             marketResolved["symbol"],
		"type":               typeVar,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               nil,
		"average":            average,
		"amount":             amount,
		"filled":             filled,
		"remaining":          remaining,
		"trades":             nil,
		"fee":                nil,
		"info":               order,
	}, marketResolved)
}

/**
 * @method
 * @name bitbank#createOrder
 * @description create a trade order
 * @see https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/rest-api.md#create-new-order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bitbank) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Bitbank) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair":   market["id"],
		"amount": this.AmountToPrecision(symbol, amount),
		"side":   side,
		"type":   typeVar,
	}
	if typeVar == "limit" {
		request["price"] = this.PriceToPrecision(symbol, price)
	}

	r1 := <-this.PrivatePostUserSpotOrder(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var data map[string]any = SafeMapTyped(response, "data")

	ch <- AsyncResult[Order]{Value: this.ParseOrder(data, market)}
	return nil
}

